-- =============================================================================
-- CURACIÓN COMPLETA DE exercises_library (136 ejercicios)
-- =============================================================================
-- Rellena las columnas de enriquecimiento añadidas por
-- exercises_library_coaching_migration.sql. Una sentencia UPDATE por ejercicio,
-- agrupadas por muscle_group. Fuente de verdad del motor de recomendaciones
-- (src/lib/engine/).
--
-- VOCABULARIO (el motor depende de estos valores exactos):
--   category           push | pull | legs | core
--   movement_pattern   horizontal_push incline_push dip chest_iso vertical_push
--                      lateral_raise front_raise vertical_pull horizontal_pull
--                      rear_delt shrug back_extension hinge squat lunge
--                      hip_extension leg_curl_iso quad_iso adduction abduction
--                      calf_raise curl triceps_extension core_anti_extension
--                      core_flexion core_rotation core_carry
--   primary/secondary_muscles  ⊆ MUSCLE_GROUPS (src/lib/muscleGroups.js):
--                      Pecho Espalda Hombro Bíceps Tríceps Core Cuádriceps
--                      Hamstrings Glúteo Gemelos.  primary_muscles[1] = muscle_group.
--   equipment          barra mancuerna polea maquina smith peso_corporal banco
--                      barra_dominadas rueda_abs
--                      (disponible ⟺ equipment ⊆ equipo del usuario)
--   difficulty         nivel MÍNIMO: Principiante | Intermedio | Avanzado
--   tracking_type      weight_reps | reps | time
--   substitution_group familia intercambiable (dedup en el día + fallback 1RM)
--   best_rep_min/max   rango efectivo del ejercicio (segundos si tracking=time)
--   coaching_notes     una indicación técnica corta (se muestra en el plan)
-- =============================================================================

-- ── PECHO ────────────────────────────────────────────────────────────────────
update exercises_library set category='push', movement_pattern='horizontal_push', primary_muscles='{Pecho}', secondary_muscles='{Tríceps,Hombro}', equipment='{barra,banco}', difficulty='Intermedio', is_compound=true, tracking_type='weight_reps', substitution_group='press_plano', best_rep_min=5, best_rep_max=10, coaching_notes='Escápulas retraídas y pies firmes; baja la barra con control al pecho medio.' where name='Press de banca con barra';
update exercises_library set category='push', movement_pattern='horizontal_push', primary_muscles='{Pecho}', secondary_muscles='{Tríceps,Hombro}', equipment='{mancuerna,banco}', difficulty='Principiante', is_compound=true, tracking_type='weight_reps', substitution_group='press_plano', best_rep_min=6, best_rep_max=12, coaching_notes='Mayor rango que con barra; no choques las mancuernas arriba.' where name='Press de banca con mancuernas';
update exercises_library set category='push', movement_pattern='horizontal_push', primary_muscles='{Pecho}', secondary_muscles='{Tríceps,Hombro}', equipment='{smith,banco}', difficulty='Principiante', is_compound=true, tracking_type='weight_reps', substitution_group='press_plano', best_rep_min=6, best_rep_max=12, coaching_notes='Coloca el banco para que la barra baje al pecho medio; trayectoria guiada, ideal para acercarte al fallo.' where name='Press de banca en Smith';
update exercises_library set category='push', movement_pattern='incline_push', primary_muscles='{Pecho}', secondary_muscles='{Hombro,Tríceps}', equipment='{barra,banco}', difficulty='Intermedio', is_compound=true, tracking_type='weight_reps', substitution_group='press_inclinado', best_rep_min=6, best_rep_max=10, coaching_notes='Banco a 30-45 grados; énfasis en pecho superior.' where name='Press inclinado con barra';
update exercises_library set category='push', movement_pattern='incline_push', primary_muscles='{Pecho}', secondary_muscles='{Hombro,Tríceps}', equipment='{mancuerna,banco}', difficulty='Principiante', is_compound=true, tracking_type='weight_reps', substitution_group='press_inclinado', best_rep_min=8, best_rep_max=12, coaching_notes='Baja profundo con control; el estiramiento del pecho superior es la parte valiosa.' where name='Press inclinado con mancuernas';
update exercises_library set category='push', movement_pattern='incline_push', primary_muscles='{Pecho}', secondary_muscles='{Hombro,Tríceps}', equipment='{smith,banco}', difficulty='Principiante', is_compound=true, tracking_type='weight_reps', substitution_group='press_inclinado', best_rep_min=8, best_rep_max=12, coaching_notes='Guiado y estable; útil para progresar cargas en inclinado sin banquero.' where name='Press inclinado en Smith';
update exercises_library set category='push', movement_pattern='horizontal_push', primary_muscles='{Pecho}', secondary_muscles='{Tríceps}', equipment='{barra,banco}', difficulty='Intermedio', is_compound=true, tracking_type='weight_reps', substitution_group='press_declinado', best_rep_min=6, best_rep_max=10, coaching_notes='Recorrido corto y fuerte; énfasis en pecho inferior.' where name='Press declinado con barra';
update exercises_library set category='push', movement_pattern='horizontal_push', primary_muscles='{Pecho}', secondary_muscles='{Tríceps}', equipment='{mancuerna,banco}', difficulty='Principiante', is_compound=true, tracking_type='weight_reps', substitution_group='press_declinado', best_rep_min=8, best_rep_max=12, coaching_notes='Controla la bajada; no rebotes en el pecho.' where name='Press declinado con mancuernas';
update exercises_library set category='push', movement_pattern='chest_iso', primary_muscles='{Pecho}', secondary_muscles='{Hombro}', equipment='{mancuerna,banco}', difficulty='Principiante', is_compound=false, tracking_type='weight_reps', substitution_group='aperturas_cruce', best_rep_min=10, best_rep_max=15, coaching_notes='Codos semiflexionados fijos; abre hasta sentir el estiramiento, sin dolor de hombro.' where name='Aperturas con mancuernas plano';
update exercises_library set category='push', movement_pattern='chest_iso', primary_muscles='{Pecho}', secondary_muscles='{Hombro}', equipment='{mancuerna,banco}', difficulty='Principiante', is_compound=false, tracking_type='weight_reps', substitution_group='aperturas_cruce', best_rep_min=10, best_rep_max=15, coaching_notes='En banco inclinado; el pecho superior trabaja más en el estiramiento.' where name='Aperturas inclinadas con mancuernas';
update exercises_library set category='push', movement_pattern='chest_iso', primary_muscles='{Pecho}', secondary_muscles='{Hombro}', equipment='{polea}', difficulty='Principiante', is_compound=false, tracking_type='weight_reps', substitution_group='aperturas_cruce', best_rep_min=10, best_rep_max=15, coaching_notes='Cruza abajo y aprieta un segundo; tensión constante del cable.' where name='Crossover en polea alta';
update exercises_library set category='push', movement_pattern='chest_iso', primary_muscles='{Pecho}', secondary_muscles='{Hombro}', equipment='{polea}', difficulty='Principiante', is_compound=false, tracking_type='weight_reps', substitution_group='aperturas_cruce', best_rep_min=10, best_rep_max=15, coaching_notes='De abajo hacia arriba; énfasis en pecho superior.' where name='Crossover en polea baja';
update exercises_library set category='push', movement_pattern='chest_iso', primary_muscles='{Pecho}', secondary_muscles='{Hombro}', equipment='{polea}', difficulty='Principiante', is_compound=false, tracking_type='weight_reps', substitution_group='aperturas_cruce', best_rep_min=10, best_rep_max=15, coaching_notes='Poleas a la altura del pecho; activación media y uniforme.' where name='Crossover en polea media';
update exercises_library set category='push', movement_pattern='horizontal_push', primary_muscles='{Pecho}', secondary_muscles='{Tríceps,Hombro}', equipment='{maquina}', difficulty='Principiante', is_compound=true, tracking_type='weight_reps', substitution_group='press_plano', best_rep_min=8, best_rep_max=12, coaching_notes='Ajusta el asiento para que las manos queden a la altura del pecho.' where name='Press en máquina pecho';
update exercises_library set category='push', movement_pattern='incline_push', primary_muscles='{Pecho}', secondary_muscles='{Hombro,Tríceps}', equipment='{maquina}', difficulty='Principiante', is_compound=true, tracking_type='weight_reps', substitution_group='press_inclinado', best_rep_min=8, best_rep_max=12, coaching_notes='Empuja sin bloquear codos del todo; mantén la tensión.' where name='Press en máquina inclinado';
update exercises_library set category='push', movement_pattern='chest_iso', primary_muscles='{Pecho}', secondary_muscles='{Hombro}', equipment='{maquina}', difficulty='Principiante', is_compound=false, tracking_type='weight_reps', substitution_group='aperturas_cruce', best_rep_min=10, best_rep_max=15, coaching_notes='Codos semiflexionados; junta y aprieta un segundo al centro.' where name='Pec deck / Mariposa';
update exercises_library set category='push', movement_pattern='dip', primary_muscles='{Pecho}', secondary_muscles='{Tríceps,Hombro}', equipment='{peso_corporal,barra_dominadas}', difficulty='Intermedio', is_compound=true, tracking_type='reps', substitution_group='fondos', best_rep_min=6, best_rep_max=12, coaching_notes='Inclina el torso hacia delante para cargar el pecho; baja hasta estirar sin dolor.' where name='Fondos en paralelas';
update exercises_library set category='push', movement_pattern='horizontal_push', primary_muscles='{Pecho}', secondary_muscles='{Tríceps,Hombro,Core}', equipment='{peso_corporal}', difficulty='Principiante', is_compound=true, tracking_type='reps', substitution_group='press_plano', best_rep_min=8, best_rep_max=20, coaching_notes='Cuerpo en línea recta; el core no se hunde.' where name='Flexiones';
update exercises_library set category='push', movement_pattern='incline_push', primary_muscles='{Pecho}', secondary_muscles='{Hombro,Tríceps,Core}', equipment='{peso_corporal,banco}', difficulty='Intermedio', is_compound=true, tracking_type='reps', substitution_group='press_inclinado', best_rep_min=8, best_rep_max=20, coaching_notes='Pies elevados; más carga en pecho superior y hombro.' where name='Flexiones inclinadas';
update exercises_library set category='push', movement_pattern='horizontal_push', primary_muscles='{Pecho}', secondary_muscles='{Tríceps,Hombro}', equipment='{peso_corporal,banco}', difficulty='Principiante', is_compound=true, tracking_type='reps', substitution_group='press_plano', best_rep_min=10, best_rep_max=20, coaching_notes='Manos elevadas; versión más accesible, ideal para acumular reps limpias.' where name='Flexiones declinadas';
update exercises_library set category='push', movement_pattern='horizontal_push', primary_muscles='{Pecho}', secondary_muscles='{Tríceps}', equipment='{peso_corporal}', difficulty='Intermedio', is_compound=true, tracking_type='reps', substitution_group='press_cerrado', best_rep_min=8, best_rep_max=15, coaching_notes='Manos juntas bajo el pecho; codos pegados al torso.' where name='Flexiones diamante';
update exercises_library set category='push', movement_pattern='chest_iso', primary_muscles='{Pecho}', secondary_muscles='{Espalda}', equipment='{polea}', difficulty='Principiante', is_compound=false, tracking_type='weight_reps', substitution_group='pullover_pecho', best_rep_min=10, best_rep_max=15, coaching_notes='Brazos casi rectos; lleva el cable en arco amplio sintiendo el estiramiento del pecho.' where name='Pull-over en polea';

-- ── ESPALDA ──────────────────────────────────────────────────────────────────
update exercises_library set category='pull', movement_pattern='vertical_pull', primary_muscles='{Espalda}', secondary_muscles='{Bíceps}', equipment='{peso_corporal,barra_dominadas}', difficulty='Intermedio', is_compound=true, tracking_type='reps', substitution_group='dominadas', best_rep_min=5, best_rep_max=12, coaching_notes='Inicia bajando las escápulas; pecho hacia la barra, sin balanceo.' where name='Dominadas agarre prono';
update exercises_library set category='pull', movement_pattern='vertical_pull', primary_muscles='{Espalda}', secondary_muscles='{Bíceps}', equipment='{peso_corporal,barra_dominadas}', difficulty='Intermedio', is_compound=true, tracking_type='reps', substitution_group='dominadas', best_rep_min=5, best_rep_max=12, coaching_notes='Agarre supino: más bíceps; controla la bajada completa.' where name='Dominadas agarre supino';
