update exercises_library set category='pull', movement_pattern='vertical_pull', primary_muscles='{Espalda}', secondary_muscles='{Bíceps}', equipment='{polea}', difficulty='Principiante', is_compound=true, tracking_type='weight_reps', substitution_group='jalon_vertical', best_rep_min=8, best_rep_max=12, coaching_notes='Agarre neutro cerrado; codos hacia las costillas.' where name='Jalón al pecho agarre cerrado';
update exercises_library set category='pull', movement_pattern='vertical_pull', primary_muscles='{Espalda}', secondary_muscles='{Bíceps}', equipment='{polea}', difficulty='Principiante', is_compound=true, tracking_type='weight_reps', substitution_group='jalon_vertical', best_rep_min=8, best_rep_max=12, coaching_notes='Palmas hacia ti; el bíceps ayuda más, buen puente hacia las dominadas.' where name='Jalón en polea alta agarre supino';
update exercises_library set category='pull', movement_pattern='horizontal_pull', primary_muscles='{Espalda}', secondary_muscles='{Bíceps,Hombro}', equipment='{barra}', difficulty='Intermedio', is_compound=true, tracking_type='weight_reps', substitution_group='remo_horizontal', best_rep_min=6, best_rep_max=10, coaching_notes='Torso a 45 grados y espalda neutra; jala hacia el abdomen, no al pecho.' where name='Remo con barra';
update exercises_library set category='pull', movement_pattern='horizontal_pull', primary_muscles='{Espalda}', secondary_muscles='{Bíceps}', equipment='{mancuerna,banco}', difficulty='Principiante', is_compound=true, tracking_type='weight_reps', substitution_group='remo_horizontal', best_rep_min=8, best_rep_max=12, coaching_notes='Rodilla y mano en el banco; jala con el codo pegado, sin rotar el torso.' where name='Remo con mancuerna unilateral';
