update exercises_library set category='pull', movement_pattern='horizontal_pull', primary_muscles='{Espalda}', secondary_muscles='{Bíceps}', equipment='{polea}', difficulty='Principiante', is_compound=true, tracking_type='weight_reps', substitution_group='remo_horizontal', best_rep_min=8, best_rep_max=12, coaching_notes='Torso erguido y estable; lleva el agarre al ombligo.' where name='Remo en polea baja';
update exercises_library set category='pull', movement_pattern='horizontal_pull', primary_muscles='{Espalda}', secondary_muscles='{Bíceps,Hombro}', equipment='{polea}', difficulty='Principiante', is_compound=true, tracking_type='weight_reps', substitution_group='remo_horizontal', best_rep_min=8, best_rep_max=12, coaching_notes='Agarre ancho: codos más abiertos, más espalda alta.' where name='Remo en polea baja agarre ancho';
update exercises_library set category='pull', movement_pattern='horizontal_pull', primary_muscles='{Espalda}', secondary_muscles='{Bíceps}', equipment='{barra}', difficulty='Intermedio', is_compound=true, tracking_type='weight_reps', substitution_group='remo_horizontal', best_rep_min=6, best_rep_max=10, coaching_notes='Cadera atrás, espalda neutra; carga pesado sin perder la postura.' where name='Remo T-bar';
