update exercises_library set category='pull', movement_pattern='vertical_pull', primary_muscles='{Espalda}', secondary_muscles='{Tríceps}', equipment='{polea}', difficulty='Principiante', is_compound=false, tracking_type='weight_reps', substitution_group='pullover_dorsal', best_rep_min=10, best_rep_max=15, coaching_notes='Empuja el cable hacia el muslo con brazos rectos; aísla el dorsal.' where name='Straight-arm pulldown';
